// DBS iBanking Alert - Extract Amount, Date and To
// v8: fixed To: extraction for HTML table format

function decodeEntities(s) {
  return s
    .replace(/&amp;/gi, '&')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"');
}

function stripHtml(s) {
  return decodeEntities(
    s
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(?:p|div|tr)>/gi, '\n')
      .replace(/<\/td>/gi, ' ')
      .replace(/<[^>]+>/g, '')
  ).replace(/[ \t]{2,}/g, ' ').trim();
}

function extractFromPayload(payload) {
  if (!payload) return '';
  let plain = '', html = '';
  function walk(node) {
    if (!node) return;
    const mime = (node.mimeType || '').toLowerCase();
    const data = node.body && node.body.data ? node.body.data : null;
    if (data) {
      const decoded = Buffer.from(data, 'base64').toString('utf-8');
      if (mime === 'text/plain') plain = plain || decoded;
      if (mime === 'text/html')  html  = html  || decoded;
    }
    if (node.parts) node.parts.forEach(walk);
  }
  walk(payload);
  return plain ? decodeEntities(plain) : stripHtml(html);
}

const results = [];

for (const item of $input.all()) {
  const subject = item.json.subject || '';

  let body = '';
  if (item.json.text && item.json.text.trim())       body = decodeEntities(item.json.text);
  else if (item.json.html && item.json.html.trim())  body = stripHtml(item.json.html);
  else if (item.json.payload)                        body = extractFromPayload(item.json.payload);
  else                                               body = decodeEntities(item.json.snippet || '');

  const content = subject + '\n' + body;

  const emailYear = item.json.date
    ? new Date(item.json.date).getFullYear()
    : new Date().getFullYear();

  // ── Amount ──────────────────────────────────────────────────────────────
  let amount = null;
  const amtPatterns = [
    /(?:SGD|S\$)\s*([\d,]+\.\d{2})/i,
    /(?:SGD|S\$)\s*([\d,]+)/i,
    /amount[:\s]+(?:SGD|S\$)?\s*([\d,]+\.?\d*)/i,
    /of\s+(?:SGD|S\$)\s*([\d,]+\.?\d*)/i,
    /(?:debit|credit)(?:ed)?[^\d]{0,20}([\d,]+\.\d{2})/i,
  ];
  for (const re of amtPatterns) {
    const m = content.match(re);
    if (m) { amount = parseFloat(m[1].replace(/,/g, '')); break; }
  }

  // ── Date ────────────────────────────────────────────────────────────────
  let txnDate = null;
  const datePatterns = [
    /(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{4})/i,
    /Date\s*[&]?\s*Time\s*:\s*(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?)(?:\s+\d{1,2}:\d{2})?/i,
    /Date\s*:\s*(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?)(?:\s+\d{4})?/i,
    /dated?\s+(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?)(?:\s+\d{4})?/i,
    /(\d{2}[\/-]\d{2}[\/-]\d{4})/,
    /(\d{4}-\d{2}-\d{2})/,
  ];
  for (const re of datePatterns) {
    const m = content.match(re);
    if (m) {
      let d = m[1].trim();
      if (!/\d{4}/.test(d)) d = d + ' ' + emailYear;
      txnDate = d;
      break;
    }
  }

  // ── To ──────────────────────────────────────────────────────────────────
  let toRecipient = null;
  const toPatterns = [
    /\bTo:\s+(?!view\b)([^\n\r]+)/i,
    /From:[^\n\r]+[\n\r]+\s*To:\s*([^\n\r]+)/i,
    /\bTo:\s{2,}([^\n\r]+)/,
  ];
  for (const re of toPatterns) {
    const m = content.match(re);
    if (m && m[1] && m[1].trim().length > 1) {
      toRecipient = m[1].trim();
      break;
    }
  }

  results.push({
    json: {
      emailId:      item.json.id,
      subject,
      from:         item.json.from,
      emailDate:    item.json.date,
      amount,
      currency:     'SGD',
      txnDate,
      to:           toRecipient,
      extractionOk: !!(amount && txnDate),
      _debug: {
        amountFound: amount      !== null,
        dateFound:   txnDate     !== null,
        toFound:     toRecipient !== null,
        bodySource:  item.json.text ? 'text' : item.json.html ? 'html' : item.json.payload ? 'payload' : 'snippet',
        bodyPreview: body.substring(0, 600)
      }
    }
  });
}

return results;
